-- Comentarios do CTN, lote 7 (arts. 151 a 168). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='ctn' and numero between 151 and 168 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(151,'','Suspensão da exigibilidade do crédito tributário','Suspendem a exigibilidade do crédito tributário: a moratória (inciso I); o depósito do seu montante integral (inciso II); as impugnações, os recursos e a manifestação de inconformidade, nos termos das leis reguladoras do processo tributário administrativo (inciso III); a concessão de medida liminar em mandado de segurança (inciso IV); a concessão de medida liminar ou de tutela provisória, em outras espécies de ação judicial (inciso V); o parcelamento (inciso VI); a instituição da arbitragem especial tributária e aduaneira, nos termos da legislação específica (inciso VII); a proposta de transação aceita pela administração, nos termos da legislação específica (inciso VIII); o acordo decorrente de mediação, até a sua eventual dissolução (inciso IX); e a aceitação, pelo credor, de apólice de seguro garantia ou de carta de fiança bancária oferecidas em execução fiscal, enquanto estiverem em conformidade com as normas que regem sua aceitação e enquanto não caracterizada hipótese de sinistro (inciso X). O § 1º dispõe que o artigo não dispensa o cumprimento das obrigações acessórias dependentes da obrigação principal cujo crédito seja suspenso, ou dela consequentes. O § 2º veda a exigência de caução ou garantia de depósito para apresentação de impugnações, recursos ou pedidos, nos termos do inciso III. O § 3º condiciona, estando em curso a execução fiscal, a suspensão pelo inciso VII à prévia suspensão da exigibilidade na execução fiscal por outra das hipóteses do caput (inciso I) ou ao oferecimento, pelo sujeito passivo, de garantia integral na arbitragem (inciso II).'),
(152,'','Moratória: concessão','A moratória somente pode ser concedida em caráter geral, pela pessoa jurídica de direito público competente para instituir o tributo a que se refira (inciso I, alínea a) ou pela União, quanto a tributos de competência dos Estados, do Distrito Federal ou dos Municípios, quando simultaneamente concedida quanto aos tributos de competência federal e às obrigações de direito privado (alínea b); e em caráter individual, por despacho da autoridade administrativa, desde que autorizada por lei nas condições do inciso anterior (inciso II). O parágrafo único dispõe que a lei concessiva pode circunscrever expressamente a sua aplicabilidade a determinada região do território da pessoa jurídica de direito público que a expedir, ou a determinada classe ou categoria de sujeitos passivos.'),
(153,'','Moratória: requisitos da lei','A lei que conceda moratória em caráter geral ou autorize sua concessão em caráter individual especificará, sem prejuízo de outros requisitos, o prazo de duração do favor (inciso I), as condições da concessão do favor em caráter individual (inciso II) e, sendo caso, os tributos a que se aplica, o número de prestações e seus vencimentos, dentro do prazo do inciso I, podendo atribuir a fixação de uns e de outros à autoridade administrativa, para cada caso de concessão em caráter individual, e as garantias que devem ser fornecidas pelo beneficiado no caso de concessão em caráter individual (inciso III, alíneas a a c).'),
(154,'','Moratória: abrangência','Salvo disposição de lei em contrário, a moratória somente abrange os créditos definitivamente constituídos à data da lei ou do despacho que a conceder, ou cujo lançamento já tenha sido iniciado àquela data por ato regularmente notificado ao sujeito passivo. O parágrafo único dispõe que a moratória não aproveita aos casos de dolo, fraude ou simulação do sujeito passivo ou do terceiro em benefício daquele.'),
(155,'','Moratória: revogação da concessão individual','A concessão da moratória em caráter individual não gera direito adquirido e será revogada de ofício, sempre que se apure que o beneficiado não satisfazia ou deixou de satisfazer as condições ou não cumprira ou deixou de cumprir os requisitos para a concessão do favor, cobrando-se o crédito acrescido de juros de mora, com imposição da penalidade cabível, nos casos de dolo ou simulação do beneficiado, ou de terceiro em benefício daquele (inciso I), e sem imposição de penalidade, nos demais casos (inciso II). O parágrafo único dispõe que, no caso do inciso I, o tempo decorrido entre a concessão da moratória e sua revogação não se computa para efeito da prescrição do direito à cobrança do crédito e que, no caso do inciso II, a revogação só pode ocorrer antes de prescrito o referido direito.'),
(155,'Art. 155-A','Parcelamento','O parcelamento será concedido na forma e condição estabelecidas em lei específica (Lei Complementar n. 104, de 2001). O § 1º dispõe que, salvo disposição de lei em contrário, o parcelamento do crédito tributário não exclui a incidência de juros e multas. O § 2º dispõe que se aplicam, subsidiariamente, ao parcelamento as disposições do CTN relativas à moratória. O § 3º, incluído pela Lei Complementar n. 118, de 2005, dispõe que lei específica disporá sobre as condições de parcelamento dos créditos tributários do devedor em recuperação judicial. O § 4º dispõe que a inexistência da lei específica a que se refere o § 3º importa na aplicação das leis gerais de parcelamento do ente da Federação ao devedor em recuperação judicial, não podendo, neste caso, ser o prazo de parcelamento inferior ao concedido pela lei federal específica.'),
(156,'','Modalidades de extinção do crédito tributário','Extinguem o crédito tributário o pagamento (inciso I); a compensação (inciso II); a transação (inciso III); a remissão (inciso IV); a prescrição e a decadência (inciso V); a conversão de depósito em renda (inciso VI); o pagamento antecipado e a homologação do lançamento nos termos do art. 150 e seus §§ 1º e 4º (inciso VII); a consignação em pagamento, nos termos do § 2º do art. 164 (inciso VIII); a decisão administrativa irreformável, assim entendida a definitiva na órbita administrativa, que não mais possa ser objeto de ação anulatória (inciso IX); a decisão judicial passada em julgado (inciso X); a dação em pagamento em bens imóveis, na forma e condições estabelecidas em lei, com a anotação "Vide Lei nº 13.259, de 2016" (inciso XI); a sentença arbitral, proferida no âmbito da arbitragem especial tributária e aduaneira, favorável ao sujeito passivo, transitada em julgado (inciso XII); e o cumprimento do acordo de mediação (inciso XIII). O parágrafo único dispõe que a lei disporá quanto aos efeitos da extinção total ou parcial do crédito sobre a ulterior verificação da irregularidade da sua constituição, observado o disposto nos arts. 144 e 149.'),
(157,'','Penalidade e pagamento integral do crédito','A imposição de penalidade não ilide o pagamento integral do crédito tributário.'),
(158,'','Pagamento: ausência de presunção de pagamento de outros créditos','O pagamento de um crédito não importa em presunção de pagamento, quando parcial, das prestações em que se decomponha (inciso I) e, quando total, de outros créditos referentes ao mesmo ou a outros tributos (inciso II).'),
(159,'','Pagamento: lugar','Quando a legislação tributária não dispuser a respeito, o pagamento é efetuado na repartição competente do domicílio do sujeito passivo.'),
(160,'','Pagamento: tempo','Quando a legislação tributária não fixar o tempo do pagamento, o vencimento do crédito ocorre trinta dias depois da data em que se considera o sujeito passivo notificado do lançamento. O parágrafo único dispõe que a legislação tributária pode conceder desconto pela antecipação do pagamento, nas condições que estabeleça.'),
(161,'','Juros de mora e multa de mora','O crédito não integralmente pago no vencimento é acrescido de juros de mora, seja qual for o motivo determinante da falta, sem prejuízo da imposição das penalidades cabíveis e da aplicação de quaisquer medidas de garantia previstas no CTN ou em lei tributária. O § 1º dispõe que, se a lei não dispuser de modo diverso, os juros de mora são calculados à taxa de um por cento ao mês. O § 2º dispõe que o artigo não se aplica na pendência de consulta formulada pelo devedor dentro do prazo legal para pagamento do crédito. O § 3º, incluído pela Lei Complementar n. 236, de 2026, dispõe que a propositura de ação judicial na qual foi concedida medida liminar ou tutela provisória interrompe a incidência da multa de mora, desde a concessão da medida judicial, até 30 (trinta) dias após a data de publicação da decisão judicial que considerar devido o tributo.'),
(162,'','Pagamento: modalidades','O pagamento é efetuado em moeda corrente, cheque ou vale postal (inciso I) e, nos casos previstos em lei, em estampilha, em papel selado, ou por processo mecânico (inciso II). O § 1º dispõe que a legislação tributária pode determinar as garantias exigidas para o pagamento por cheque ou vale postal, desde que não o torne impossível ou mais oneroso que o pagamento em moeda corrente. O § 2º dispõe que o crédito pago por cheque somente se considera extinto com o resgate deste pelo sacado. O § 3º dispõe que o crédito pagável em estampilha considera-se extinto com a inutilização regular daquela, ressalvado o disposto no art. 150. O § 4º dispõe que a perda ou destruição da estampilha, ou o erro no pagamento por esta modalidade, não dão direito a restituição, salvo nos casos expressamente previstos na legislação tributária, ou naqueles em que o erro seja imputável à autoridade administrativa. O § 5º equipara o pagamento em papel selado ou por processo mecânico ao pagamento em estampilha.'),
(163,'','Imputação em pagamento','Existindo simultaneamente dois ou mais débitos vencidos do mesmo sujeito passivo para com a mesma pessoa jurídica de direito público, relativos ao mesmo ou a diferentes tributos ou provenientes de penalidade pecuniária ou juros de mora, a autoridade administrativa competente para receber o pagamento determinará a respectiva imputação, obedecidas as seguintes regras, na ordem em que enumeradas: em primeiro lugar, aos débitos por obrigação própria e, em segundo lugar, aos decorrentes de responsabilidade tributária (inciso I); primeiramente, às contribuições de melhoria, depois às taxas e por fim aos impostos (inciso II); na ordem crescente dos prazos de prescrição (inciso III); e na ordem decrescente dos montantes (inciso IV).'),
(164,'','Consignação em pagamento','A importância de crédito tributário pode ser consignada judicialmente pelo sujeito passivo nos casos de recusa de recebimento, ou subordinação deste ao pagamento de outro tributo ou de penalidade, ou ao cumprimento de obrigação acessória (inciso I); de subordinação do recebimento ao cumprimento de exigências administrativas sem fundamento legal (inciso II); e de exigência, por mais de uma pessoa jurídica de direito público, de tributo idêntico sobre um mesmo fato gerador (inciso III). O § 1º dispõe que a consignação só pode versar sobre o crédito que o consignante se propõe pagar. O § 2º dispõe que, julgada procedente a consignação, o pagamento se reputa efetuado e a importância consignada é convertida em renda e que, julgada improcedente no todo ou em parte, cobra-se o crédito acrescido de juros de mora, sem prejuízo das penalidades cabíveis.'),
(165,'','Restituição do indébito','O sujeito passivo tem direito, independentemente de prévio protesto, à restituição total ou parcial do tributo, seja qual for a modalidade do seu pagamento, ressalvado o disposto no § 4º do art. 162, nos casos de cobrança ou pagamento espontâneo de tributo indevido ou maior que o devido em face da legislação tributária aplicável, ou da natureza ou circunstâncias materiais do fato gerador efetivamente ocorrido (inciso I); de erro na edificação do sujeito passivo, na determinação da alíquota aplicável, no cálculo do montante do débito ou na elaboração ou conferência de qualquer documento relativo ao pagamento, conforme a redação do dispositivo na fonte (inciso II); e de reforma, anulação, revogação ou rescisão de decisão condenatória (inciso III).'),
(165,'Art. 165-A','Atualização dos indébitos tributários','Os indébitos tributários serão atualizados pelos mesmos índices de atualização dos créditos tributários da União, dos Estados, do Distrito Federal e dos Municípios, conforme o caso (Lei Complementar n. 236, de 2026).'),
(166,'','Restituição de tributos que comportem transferência do encargo financeiro','A restituição de tributos que comportem, por sua natureza, transferência do respectivo encargo financeiro somente será feita a quem prove haver assumido o referido encargo, ou, no caso de tê-lo transferido a terceiro, estar por este expressamente autorizado a recebê-la.'),
(167,'','Restituição: juros de mora e penalidades','A restituição total ou parcial do tributo dá lugar à restituição, na mesma proporção, dos juros de mora e das penalidades pecuniárias, salvo as referentes a infrações de caráter formal não prejudicadas pela causa da restituição. O parágrafo único dispõe que a restituição vence juros não capitalizáveis, a partir do trânsito em julgado da decisão definitiva que a determinar.'),
(168,'','Prazo para pleitear a restituição','O direito de pleitear a restituição extingue-se com o decurso do prazo de 5 (cinco) anos, contados, nas hipóteses dos incisos I e II do art. 165, da data da extinção do crédito tributário (inciso I, com a anotação "Vide art 3 da LCp nº 118, de 2005") e, na hipótese do inciso III do art. 165, da data em que se tornar definitiva a decisão administrativa ou passar em julgado a decisão judicial que tenha reformado, anulado, revogado ou rescindido a decisão condenatória (inciso II). O § 1º consta como vetado e está registrado como não vigente. O § 2º, incluído pela Lei Complementar n. 236, de 2026, dispõe que o caput aplica-se à habilitação do indébito perante a administração tributária. O § 3º dispõe que o prazo para habilitação do § 2º contar-se-á da certificação do trânsito em julgado.')
) as v(n,t,c,a)
where l.codigo='ctn' and l.numero=v.n and coalesce(l.titulo,'')=v.t and l.paragrafo is null and l.inciso is null and l.vigente;
